/bin/zsh -lc "python3 - <<'PY'
import json
from pathlib import Path
for name in ('policy.json','coordination.json'):
 print('\\nFILE', name)
 print(Path(name).read_text())
s=json.loads(Path('source.json').read_text())
print('\\nSOURCE TYPE',type(s).__name__)
if isinstance(s,dict):
 print('KEYS',list(s))
 for k,v in s.items():
  if isinstance(v,list): print('LIST',k,len(v))
else:
 print('COUNT',len(s))
for i,a in enumerate(s if isinstance(s,list) else next(v for v in s.values() if isinstance(v,list))):
 print(i, {k:v for k,v in a.items() if k not in ('source_xml','source_notes_xml')},'XML_LEN',len(a.get('source_xml','')),'NOTES_LEN',len(a.get('source_notes_xml','') or ''))
PY"

